#include "common.hpp"

#include <mutex>

using namespace JPH;

// Jolt itself is set up once for all worlds.
namespace {
std::mutex jolt_lock;
uint32_t   jolt_users = 0;
}

void jolt_acquire()
{
	std::lock_guard<std::mutex> guard(jolt_lock);
	if (jolt_users++ == 0) {
		RegisterDefaultAllocator();
		Factory::sInstance = new Factory();
		RegisterTypes();
		// Nothing is ever made from a saved shape, but the table has to know the sub type.
		ShapeFunctions& functions = ShapeFunctions::sGet(EShapeSubType::UserConvex1);
		functions.mConstruct      = []() -> Shape* { return nullptr; };
		functions.mColor          = Color::sRed;
	}
}

void jolt_release()
{
	std::lock_guard<std::mutex> guard(jolt_lock);
	if (--jolt_users == 0) {
		UnregisterTypes();
		delete Factory::sInstance;
		Factory::sInstance = nullptr;
	}
}

